fn saturating_increment<N: u32>(x: uN[N]) -> uN[N] {
  const MAX = all_ones!<uN[N]>();
  if x == MAX { x } else { x + uN[N]:1 }
}

const_assert!(saturating_increment(u8:41) == u8:42);

enum Mode : u2 {
  IDLE = 0,
  RUN = 1,
  FAULT = 2,
}

struct Status {
  mode: Mode,
  payload: u32,
}

fn read(status: Status) -> u32 {
  match status.mode {
    Mode::RUN => status.payload,
    Mode::FAULT => u32:0xffff_ffff,
    _ => u32:0,
  }
}

fn replace_lane(values: u16[4], lane: u32, value: u16) -> u16[4] {
  update(values, lane, value)
}

fn unpack(word: u32) -> (u8, u8, u16) {
  let low = word[0+:u8];
  let middle = word[8:16];
  let high = word[16+:u16];
  (low, middle, high)
}

fn repack(parts: (u8, u8, u16)) -> u32 {
  parts.2 ++ parts.1 ++ parts.0
}

proc Counter {
  output: chan<u32> out;

  config(output: chan<u32> out) {
    (output,)
  }

  init { u32:0 }

  next(state: u32) {
    send(join(), output, state);
    state + u32:1
  }
}
